"use client";
import Link from "next/link";
import { useEffect,useState,type FormEvent } from "react";
import { useRouter } from "next/navigation";
import { EmailAuthProvider,GoogleAuthProvider,linkWithCredential,sendPasswordResetEmail,signInWithEmailAndPassword,signInWithPopup,signOut } from "firebase/auth";
import { firebaseAuth } from "./firebase";
type Clinic={id:string;displayName:string;legalName:string;status:string;role:string};type Doctor={id:string;displayName:string|null;status:string;professionalVerificationStatus:string;connectionId?:string;connectionStatus?:"REQUESTED"|"ACCEPTED";connectionInitiatorKind?:"CLINIC"|"DOCTOR"};export type Context={clinics:Clinic[];doctor:Doctor|null};export type Service={id:string;name:string;description?:string|null;status:string;versionId:string|null;versionStatus:string|null;availabilityStatus:string|null;exposureId:string|null;exposureStatus:string|null;publicDiscoveryStatus:string|null};type Appointment={id:string;status:string;startsAt:string;endsAt:string;serviceName:string};export type Availability={id:string;serviceOfferingVersionId:string;providerTimezone:string;slotDurationSeconds:number;bufferBeforeSeconds:number;bufferAfterSeconds:number;capacity:number;bookingLeadTimeSeconds:number;bookingHorizonSeconds:number;status:string;rules:{recurrence:string;effectiveFrom:string;effectiveTo:string|null;windows:{kind:"WORKING"|"BREAK";weekday:number;startSeconds:number;endSeconds:number}[]}[]};
const configuredBase=process.env.NEXT_PUBLIC_PLATFORM_API_BASE_URL?.replace(/\/$/,"")??"";const base=configuredBase.startsWith("http://127.0.0.1")?"":configuredBase;
export async function api<T>(path:string,init?:RequestInit):Promise<T>{const r=await fetch(`${base}${path}`,{...init,credentials:"include"});if(!r.ok){let detail:string|undefined;try{const body=await r.json() as {message?:unknown;error?:{message?:unknown}};const value=body.error?.message??body.message;if(typeof value==="string"&&value.trim())detail=value;}catch{}const fallback=r.status===401?"Your provider session has expired. Sign in again.":r.status===403?"You are not permitted to perform this provider operation.":r.status===404?"The requested provider resource was not found.":"The provider operation could not be completed.";throw new Error(detail??fallback);}return r.status===204?undefined as T:r.json();}
export async function context(){return api<Context>("/v1/provider/context");}
function authenticationError(cause:unknown){const code=typeof cause==="object"&&cause!==null&&"code" in cause?String(cause.code):"";if(code==="auth/invalid-credential"||code==="auth/wrong-password"||code==="auth/user-not-found")return "The email address or password is incorrect.";if(code==="auth/invalid-email")return "Enter a valid email address.";if(code==="auth/too-many-requests")return "Too many attempts. Please try again later or reset your password.";if(code==="auth/popup-closed-by-user")return "Google sign-in was cancelled.";return cause instanceof Error?cause.message:"Authentication was not completed.";}
export function SignIn(){const router=useRouter();const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[error,setError]=useState<string>();const[notice,setNotice]=useState<string>();const[busy,setBusy]=useState(false);async function establish(user:{getIdToken:(force?:boolean)=>Promise<string>}){await api("/v1/auth/provider/firebase/session",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({idToken:await user.getIdToken(true)})});router.push("/dashboard");}async function passwordSignIn(event:FormEvent<HTMLFormElement>){event.preventDefault();setError(undefined);setNotice(undefined);setBusy(true);try{const credential=await signInWithEmailAndPassword(firebaseAuth(),email.trim(),password);await establish(credential.user);}catch(cause){setError(authenticationError(cause));}finally{setBusy(false);}}async function googleSignIn(){setError(undefined);setNotice(undefined);setBusy(true);try{const credential=await signInWithPopup(firebaseAuth(),new GoogleAuthProvider());await establish(credential.user);}catch(cause){setError(authenticationError(cause));}finally{setBusy(false);}}async function resetPassword(){setError(undefined);setNotice(undefined);const normalizedEmail=email.trim();if(!normalizedEmail){setError("Enter your email address before requesting a password reset.");return;}setBusy(true);try{await sendPasswordResetEmail(firebaseAuth(),normalizedEmail);setNotice("If that email has a Firebase account, a password-reset message has been sent.");}catch(cause){setError(authenticationError(cause));}finally{setBusy(false);}}return <main className="login panel"><p className="brand" style={{color:"#176b50"}}>THE CLINIQ</p><h1>Provider sign in</h1><p className="muted">For clinic teams and doctors. Platform administrators use the Platform Admin application.</p><button disabled={busy} onClick={()=>void googleSignIn()}>Continue with Google</button><form onSubmit={(event)=>void passwordSignIn(event)}><label>Email<input autoComplete="email" disabled={busy} onChange={(event)=>setEmail(event.target.value)} type="email" value={email}/></label><label>Password<input autoComplete="current-password" disabled={busy} onChange={(event)=>setPassword(event.target.value)} type="password" value={password}/></label><button disabled={busy} type="submit">{busy?"Signing in…":"Sign in with email"}</button></form><button className="link-button" disabled={busy} onClick={()=>void resetPassword()} type="button">Forgot password?</button>{notice?<p className="muted">{notice}</p>:null}{error?<p className="error">{error}</p>:null}</main>}
export function ProviderShell({children}:{children:React.ReactNode}){const router=useRouter();const[c,setC]=useState<Context>();const[e,setE]=useState<string>();useEffect(()=>{void context().then(setC).catch(x=>setE(x.message));},[]);async function logout(){await fetch(`${base}/v1/auth/session/logout`,{method:"POST",credentials:"include"});await signOut(firebaseAuth());router.push("/sign-in");}if(e)return <main className="login panel"><h1>Provider access unavailable</h1><p className="error">{e}</p><Link href="/sign-in">Sign in</Link></main>;if(!c)return <main className="login panel">Checking your secure provider session…</main>;const clinic=c.clinics[0];const doctor=c.doctor;const clinicUser=!!clinic;const title=clinicUser?clinic.displayName:doctor?.displayName??"Doctor";const role=clinicUser?clinic.role:"DOCTOR";const nav=clinicUser?[["Dashboard","/dashboard"],["Clinic profile","/clinic/profile"],["Services","/clinic/services"],["Doctors","/clinic/doctors"],["Availability","/clinic/availability"],["Appointments","/clinic/appointments"]]:[["Dashboard","/dashboard"],["My profile","/doctor/profile"],["My services","/doctor/services"],["My availability","/doctor/availability"],["My appointments","/doctor/appointments"],["Account security","/doctor/security"]];return <div className="shell"><aside className="side"><div className="brand">THE CLINIQ</div><div className="context"><strong>{title}</strong><br/><small>{role}</small></div><nav className="nav">{nav.map(([label,href])=><Link key={href} href={href}>{label}</Link>)}<button className="nav-button" onClick={()=>void logout()}>Logout</button></nav></aside><main className="main">{children}</main></div>}
export function ProviderPage({page}:{page:"dashboard"|"profile"|"services"|"doctors"|"availability"|"appointments"}){const[c,setC]=useState<Context>();const[e,setE]=useState<string>();const[data,setData]=useState<unknown>();useEffect(()=>{void context().then(setC).catch(x=>setE(x.message));},[]);useEffect(()=>{if(!c)return;const clinic=c.clinics[0];const paths={dashboard:clinic?`/v1/provider/clinics/${clinic.id}/dashboard`:"/v1/provider/doctor/appointments",services:clinic?`/v1/provider/clinics/${clinic.id}/services`:"/v1/provider/doctor/services",doctors:clinic?`/v1/provider/clinics/${clinic.id}/doctors`:"/v1/provider/doctor/services",appointments:clinic?`/v1/provider/clinics/${clinic.id}/appointments`:"/v1/provider/doctor/appointments",profile:"/v1/provider/context",availability:clinic?`/v1/provider/clinics/${clinic.id}/services`:"/v1/provider/doctor/services"};void api(paths[page]).then(setData).catch(x=>setE(x.message));},[c,page]);if(e)return <main className="login panel"><h1>Provider access unavailable</h1><p className="error">{e}</p><Link href="/sign-in">Sign in</Link></main>;if(!c)return <main className="login panel">Checking your secure provider session…</main>;const clinic=c.clinics[0];const doctor=c.doctor;const clinicUser=!!clinic;const title=clinicUser?clinic.displayName:doctor?.displayName??"Doctor";return <ProviderShell><p className="eyebrow">{clinicUser?"Clinic operations":"Doctor operations"}</p><h1>Dashboard</h1>{doctor?.professionalVerificationStatus==="PENDING"?<section className="panel"><strong>Professional verification: Pending</strong><p className="muted">Publication is controlled by The CliniQ Platform.</p></section>:null}<section className="cards">{page==="dashboard"&&clinicUser&&data&&typeof data==="object"?Object.entries(data as Record<string,unknown>).filter(([key])=>key!=="clinic").map(([key,value])=><article className="card" key={key}><span className="muted">{key}</span><div className="metric">{String(value)}</div></article>):null}</section><section className="panel section"><h2>{title}</h2><p className="muted">Role: {clinicUser?clinic.role:"Doctor"}</p></section></ProviderShell>}
type Evidence={id:string;originalFilename:string;contentType:string;byteSize:number;status:string};type VerificationSubmission={id:string;status:"PENDING"|"APPROVED"|"REJECTED";registrationAuthority:string;registrationJurisdiction:string;registrationIdentifier:string;submittedAt:string;rejectionReason:string|null;documentFileIds:string[]};
function PasswordIdentitySetup(){const[password,setPassword]=useState("");const[confirmPassword,setConfirmPassword]=useState("");const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);async function enable(){const auth=firebaseAuth();const current=auth.currentUser;if(!current?.email){setMessage("Sign in with your linked Google account before adding email/password sign-in.");return;}if(password.length<8||password!==confirmPassword){setMessage("Use matching passwords of at least 8 characters.");return;}setBusy(true);setMessage("");try{try{await linkWithCredential(current,EmailAuthProvider.credential(current.email,password));}catch(error){if(!(typeof error==="object"&&error!==null&&"code" in error&&String(error.code)==="auth/provider-already-linked"))throw error;}const email=current.email;await signOut(auth);const credential=await signInWithEmailAndPassword(auth,email,password);const idToken=await credential.user.getIdToken(true);await api("/v1/auth/provider/firebase/password-identity",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({idToken})});await api("/v1/auth/provider/firebase/session",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({idToken})});setPassword("");setConfirmPassword("");setMessage("Email/password sign-in is now linked to this Provider account.");}catch(error){setMessage(error instanceof Error?error.message:"Unable to add email/password sign-in.");}finally{setBusy(false);}}return <section className="panel"><h2>Email/password sign-in</h2><p className="muted">After signing in with your linked Google account, add a password to the same Firebase account. The Provider API verifies and links the resulting password identity before it can be used for future Provider sign-ins.</p><label>New password<input autoComplete="new-password" disabled={busy} onChange={event=>setPassword(event.target.value)} type="password" value={password}/></label><label>Confirm password<input autoComplete="new-password" disabled={busy} onChange={event=>setConfirmPassword(event.target.value)} type="password" value={confirmPassword}/></label><button disabled={busy||!password||!confirmPassword} onClick={()=>void enable()}>{busy?"Linking…":"Enable email/password sign-in"}</button>{message?<p className={message.includes("now linked")?"feedback":"error"}>{message}</p>:null}</section>}
export function DoctorPasswordIdentitySetup(){return <ProviderShell><section className="page"><p className="eyebrow">Doctor account security</p><h1>Email/password sign-in</h1><PasswordIdentitySetup/></section></ProviderShell>}
export function DoctorVerificationProfile(){const[c,setC]=useState<Context>();const[e,setE]=useState("");const[evidence,setEvidence]=useState<Evidence[]>([]);const[submissions,setSubmissions]=useState<VerificationSubmission[]>([]);const[authority,setAuthority]=useState("");const[jurisdiction,setJurisdiction]=useState("");const[identifier,setIdentifier]=useState("");const[selected,setSelected]=useState<string[]>([]);const[busy,setBusy]=useState(false);async function load(value:Context){setC(value);const doctor=value.doctor;if(!doctor)return;const[files,records]=await Promise.all([api<{items:Evidence[]}>(`/v1/me/doctor-profiles/${doctor.id}/verification-evidence`),api<{items:VerificationSubmission[]}>(`/v1/me/doctor-profiles/${doctor.id}/verification-submissions`)]);setEvidence(files.items);setSubmissions(records.items);const pending=records.items.find(item=>item.status==="PENDING");if(pending){setAuthority(pending.registrationAuthority);setJurisdiction(pending.registrationJurisdiction);setIdentifier(pending.registrationIdentifier);setSelected(pending.documentFileIds);}}useEffect(()=>{void context().then(load).catch(x=>setE(x instanceof Error?x.message:"Unable to load professional verification."));},[]);const doctor=c?.doctor;async function upload(file:File){if(!doctor)return;setBusy(true);setE("");try{const body=await base64(file);await api(`/v1/me/doctor-profiles/${doctor.id}/verification-evidence`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({originalFilename:file.name,contentType:file.type,contentBase64:body})});await load(c!);}catch(x){setE(x instanceof Error?x.message:"Unable to upload evidence.");}finally{setBusy(false);}}async function submit(){if(!doctor||!authority.trim()||!jurisdiction.trim()||!identifier.trim()||selected.length===0)return;setBusy(true);setE("");try{await api(`/v1/me/doctor-profiles/${doctor.id}/verification-submissions`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({registrationAuthority:authority,registrationJurisdiction:jurisdiction,registrationIdentifier:identifier,documentFileIds:selected})});await load(c!);}catch(x){setE(x instanceof Error?x.message:"Unable to submit verification.");}finally{setBusy(false);}}function toggle(id:string){setSelected(current=>current.includes(id)?current.filter(value=>value!==id):[...current,id]);}if(!c)return <main className="login panel">Loading professional verification…</main>;if(!doctor)return <ProviderShell><section className="panel"><h1>Professional verification</h1><p className="muted">A doctor profile is required for this area.</p></section></ProviderShell>;const current=submissions[0];return <ProviderShell><section className="page"><p className="eyebrow">Doctor onboarding</p><h1>Professional verification</h1><section className="panel"><h2>Current status</h2><p><span className="status-badge">{doctor.professionalVerificationStatus}</span></p>{current?.rejectionReason?<p className="error">Previous submission was rejected: {current.rejectionReason}</p>:null}{doctor.professionalVerificationStatus==="VERIFIED"?<p className="feedback">Your professional verification is approved.</p>:null}</section>{doctor.professionalVerificationStatus!=="VERIFIED"?<section className="panel"><h2>Registration evidence</h2><p className="muted">Upload a PDF, JPEG, or PNG registration document. Files remain private and are available only to you and authorized Platform reviewers.</p><label>Upload evidence<input accept="application/pdf,image/jpeg,image/png" disabled={busy} onChange={event=>{const file=event.target.files?.[0];if(file)void upload(file);event.currentTarget.value="";}} type="file"/></label>{evidence.length?<ul>{evidence.map(file=><li key={file.id}><label><input checked={selected.includes(file.id)} disabled={busy||file.status!=="AVAILABLE"} onChange={()=>toggle(file.id)} type="checkbox"/> {file.originalFilename} <span className="muted">({file.contentType}, {file.byteSize} bytes)</span></label></li>)}</ul>:<p className="muted">No private evidence has been uploaded.</p>}<label>Registration authority<input disabled={busy} value={authority} onChange={event=>setAuthority(event.target.value)}/></label><label>Jurisdiction<input disabled={busy} value={jurisdiction} onChange={event=>setJurisdiction(event.target.value)}/></label><label>Registration identifier<input disabled={busy} value={identifier} onChange={event=>setIdentifier(event.target.value)}/></label><button disabled={busy||!authority.trim()||!jurisdiction.trim()||!identifier.trim()||selected.length===0} onClick={()=>void submit()}>{busy?"Saving…":current?.status==="PENDING"?"Update submission":"Submit for review"}</button></section>:null}{e?<p className="error">{e}</p>:null}</section></ProviderShell>}
async function base64(file:File){const bytes=new Uint8Array(await file.arrayBuffer());let text="";for(let offset=0;offset<bytes.length;offset+=0x8000)text+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));return btoa(text);}
type ClinicDetail={id:string;displayName:string;legalName:string;status:string};
export function ClinicProfile(){const[c,setC]=useState<Context>();const[detail,setDetail]=useState<ClinicDetail>();const[draft,setDraft]=useState<ClinicDetail>();const[editing,setEditing]=useState(false);const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);useEffect(()=>{void context().then(setC).catch(x=>setMessage(x.message));},[]);useEffect(()=>{const clinic=c?.clinics[0];if(clinic)void api<ClinicDetail>(`/v1/me/clinic/${clinic.id}`).then(value=>{setDetail(value);setDraft(value);}).catch(x=>setMessage(x.message));},[c]);if(!detail||!draft)return <section className="page-loading">Loading clinic profile…</section>;const canManage=c?.clinics[0]?.role!=="CLINIC_STAFF";async function save(){const valueToSave=draft;if(!valueToSave)return;setBusy(true);setMessage("");try{const value=await api<ClinicDetail>(`/v1/me/clinic/${valueToSave.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({legalName:valueToSave.legalName,displayName:valueToSave.displayName})});setDetail(value);setDraft(value);setEditing(false);setMessage("Clinic profile saved.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to save clinic profile.");}finally{setBusy(false);}}function cancel(){setDraft(detail);setEditing(false);setMessage("");}return <section className="page"><p className="eyebrow">Clinic operations</p><h1>Clinic Profile</h1><section className="panel"><h2>Clinic details</h2><label>Clinic name<input disabled={!editing||busy} value={draft.displayName} onChange={e=>setDraft({...draft,displayName:e.target.value})}/></label><label>Legal name<input disabled={!editing||busy} value={draft.legalName} onChange={e=>setDraft({...draft,legalName:e.target.value})}/></label><p className="muted">Status: <span className="status-badge">{detail.status}</span></p>{canManage?(editing?<div className="actions"><button disabled={busy} onClick={()=>void save()}>{busy?"Saving…":"Save"}</button><button className="secondary-button" disabled={busy} onClick={cancel}>Cancel</button></div>:<button onClick={()=>{setDraft(detail);setEditing(true);setMessage("");}}>Edit</button>):<p className="muted">Your current clinic role is read-only.</p>}{message?<p className="feedback">{message}</p>:null}</section></section>}
export function ClinicServices(){const[c,setC]=useState<Context>();const[items,setItems]=useState<Service[]>([]);const[name,setName]=useState("");const[description,setDescription]=useState("");const[editing,setEditing]=useState<Service>();const[versioning,setVersioning]=useState<Service>();const[versionNumber,setVersionNumber]=useState("1");const[effectiveFrom,setEffectiveFrom]=useState("");const[currency,setCurrency]=useState("INR");const[amountMinor,setAmountMinor]=useState("");const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);const[ready,setReady]=useState(false);const load=async(clinic:Clinic)=>setItems((await api<{items:Service[]}>(`/v1/provider/clinics/${clinic.id}/services`)).items);useEffect(()=>{void context().then(value=>{setC(value);if(value.clinics[0])void load(value.clinics[0]).catch(x=>setMessage(x.message));}).catch(x=>setMessage(x.message)).finally(()=>setReady(true));},[]);if(!ready)return <main className="login panel">Loading clinic services…</main>;const clinic=c?.clinics[0];const canManage=clinic!==undefined&&clinic.role!=="CLINIC_STAFF";async function create(){if(!clinic||!name.trim())return;setBusy(true);setMessage("");try{await api("/v1/service-offerings",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({owner:{kind:"CLINIC",clinicId:clinic.id},name:name.trim(),description:description||null,status:"DRAFT"})});setName("");setDescription("");await load(clinic);setMessage("Service created as Draft.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to create service.");}finally{setBusy(false);}}async function saveEdit(){if(!clinic||!editing||!editing.name.trim())return;setBusy(true);setMessage("");try{await api(`/v1/service-offerings/${editing.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({name:editing.name.trim(),description:editing.description||null,status:editing.status})});setEditing(undefined);await load(clinic);setMessage("Service saved.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to save service.");}finally{setBusy(false);}}async function toggle(item:Service){if(!clinic)return;const status=item.status==="ACTIVE"?"ARCHIVED":"ACTIVE";if(status==="ARCHIVED"&&!confirm(`Deactivate ${item.name}?`))return;setBusy(true);setMessage("");try{await api(`/v1/service-offerings/${item.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({name:item.name,description:item.description||null,status})});await load(clinic);setMessage(status==="ACTIVE"?"Service activated.":"Service deactivated.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to update service.");}finally{setBusy(false);}}function openVersion(item:Service){setVersioning(item);setVersionNumber("1");setEffectiveFrom("");setCurrency("INR");setAmountMinor("");setMessage("");}async function createVersion(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!clinic||!versioning)return;const number=Number(versionNumber);const effectiveAt=new Date(effectiveFrom);if(!Number.isInteger(number)||number<=0||Number.isNaN(effectiveAt.getTime())||!/^[A-Z]{3}$/.test(currency.trim().toUpperCase())||!/^(0|[1-9]\d*)$/.test(amountMinor)){setMessage("Enter a valid version number, effective date, ISO currency, and non-negative price in minor units.");return;}setBusy(true);setMessage("");try{await api(`/v1/service-offerings/${versioning.id}/versions`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({versionNumber:number,status:"ACTIVE",effectiveFrom:effectiveAt.toISOString(),currency:currency.trim().toUpperCase(),amountMinor})});setVersioning(undefined);await load(clinic);setMessage("Active service version created.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to create service version.");}finally{setBusy(false);}}async function createExposure(item:Service){if(!clinic)return;setBusy(true);setMessage("");try{await api("/v1/service-exposures",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({serviceOfferingId:item.id})});await load(clinic);setMessage("Service exposure created as Draft. Publish it separately; Platform Admin approval remains separate.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to create service exposure.");}finally{setBusy(false);}}async function publishExposure(item:Service){if(!clinic||!item.exposureId)return;setBusy(true);setMessage("");try{await api(`/v1/service-exposures/${item.exposureId}/publish`,{method:"POST"});await load(clinic);setMessage("Service exposure published. Platform Admin public-discovery approval remains separate.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to publish service exposure.");}finally{setBusy(false);}}return <main className="main"><h1>Clinic Services</h1>{canManage?<section className="panel"><h2>Add Service</h2><label>Name<input disabled={busy} value={name} onChange={e=>setName(e.target.value)}/></label><label>Description<textarea disabled={busy} value={description} onChange={e=>setDescription(e.target.value)}/></label><button disabled={busy||!name.trim()} onClick={()=>void create()}>Add Service</button></section>:<p className="muted">Your current clinic role is read-only.</p>}<section className="panel"><h2>Services</h2><ul>{items.map(item=>{const exposureReady=item.status==="ACTIVE"&&item.versionStatus==="ACTIVE"&&item.availabilityStatus==="ACTIVE";return <li key={item.id}>{editing?.id===item.id?<><label>Name<input disabled={busy} value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})}/></label><label>Description<textarea disabled={busy} value={editing.description??""} onChange={e=>setEditing({...editing,description:e.target.value})}/></label><button disabled={busy||!editing.name.trim()} onClick={()=>void saveEdit()}>{busy?"Saving…":"Save"}</button><button disabled={busy} onClick={()=>setEditing(undefined)}>Cancel</button></>:<><strong>{item.name}</strong>{item.description?` — ${item.description}`:""} · Service: {item.status} · Version: {item.versionStatus??"Not configured"} · Availability: {item.availabilityStatus??"Not configured"} · Exposure: {item.exposureStatus??"Not created"} · Platform approval: {item.publicDiscoveryStatus??"Not published"}{exposureReady&&!item.exposureId?<p className="muted">Ready to create a service exposure.</p>:null}{canManage?<><button disabled={busy} onClick={()=>setEditing(item)}>Edit</button><button disabled={busy} onClick={()=>void toggle(item)}>{item.status==="ACTIVE"?"Deactivate":"Activate"}</button>{item.status==="ACTIVE"&&!item.versionId?<button disabled={busy} onClick={()=>openVersion(item)}>Create active version</button>:null}{exposureReady&&!item.exposureId?<button disabled={busy} onClick={()=>void createExposure(item)}>Create exposure</button>:null}{item.exposureId&&(item.exposureStatus==="DRAFT"||item.exposureStatus==="UNPUBLISHED")?<button disabled={busy} onClick={()=>void publishExposure(item)}>Publish exposure</button>:null}</>:null}</>}</li>;})}</ul>{items.length===0?<p className="muted">No services have been created for this clinic.</p>:null}{message?<p className="muted">{message}</p>:null}</section>{canManage&&versioning?<section className="panel"><h2>Create active version for {versioning.name}</h2><p className="muted">This creates an effective active version. Availability remains configured separately.</p><form onSubmit={event=>void createVersion(event)}><label>Version number<input disabled={busy} inputMode="numeric" value={versionNumber} onChange={event=>setVersionNumber(event.target.value)}/></label><label>Effective from<input disabled={busy} required type="datetime-local" value={effectiveFrom} onChange={event=>setEffectiveFrom(event.target.value)}/></label><label>Currency<input disabled={busy} maxLength={3} value={currency} onChange={event=>setCurrency(event.target.value)}/></label><label>Price amount (minor units)<input disabled={busy} inputMode="numeric" value={amountMinor} onChange={event=>setAmountMinor(event.target.value)}/></label><div className="actions"><button disabled={busy} type="submit">{busy?"Creating…":"Create active version"}</button><button className="secondary-button" disabled={busy} onClick={()=>setVersioning(undefined)} type="button">Cancel</button></div></form></section>:null}</main>}
function seconds(value:string){const match=/^(\d{2}):(\d{2})$/.exec(value);return match?Number(match[1])*3600+Number(match[2])*60:NaN;}function time(value:number){return `${String(Math.floor(value/3600)).padStart(2,"0")}:${String(Math.floor(value%3600/60)).padStart(2,"0")}`;}const weekdays=["","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"];
export function ClinicAvailability(){const[c,setC]=useState<Context>();const[items,setItems]=useState<Service[]>([]);const[details,setDetails]=useState<Record<string,Availability>>({});const[selected,setSelected]=useState<Service>();const[providerTimezone,setProviderTimezone]=useState("");const[slotDuration,setSlotDuration]=useState("");const[bufferBefore,setBufferBefore]=useState("0");const[bufferAfter,setBufferAfter]=useState("0");const[capacity,setCapacity]=useState("");const[leadTime,setLeadTime]=useState("0");const[horizon,setHorizon]=useState("");const[recurrence,setRecurrence]=useState("");const[effectiveFrom,setEffectiveFrom]=useState("");const[weekday,setWeekday]=useState("1");const[start,setStart]=useState("");const[end,setEnd]=useState("");const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);const[ready,setReady]=useState(false);async function load(clinic:Clinic){const services=(await api<{items:Service[]}>(`/v1/provider/clinics/${clinic.id}/services`)).items;setItems(services);const entries=await Promise.all(services.filter(item=>item.versionId&&item.availabilityStatus).map(async item=>{try{return [item.versionId!,await api<Availability>(`/v1/service-offering-versions/${item.versionId}/availability`)] as const;}catch{return null;}}));setDetails(Object.fromEntries(entries.filter((item):item is readonly [string,Availability]=>item!==null)));}useEffect(()=>{void context().then(value=>{setC(value);if(value.clinics[0])return load(value.clinics[0]);}).catch(x=>setMessage(x instanceof Error?x.message:"Unable to load availability.")).finally(()=>setReady(true));},[]);if(!ready)return <main className="login panel">Loading clinic availability…</main>;const clinic=c?.clinics[0];const canManage=clinic!==undefined&&clinic.role!=="CLINIC_STAFF";function openCreate(service:Service){setSelected(service);setMessage("");}async function create(){if(!clinic||!selected?.versionId)return;const numbers=[Number(slotDuration),Number(bufferBefore),Number(bufferAfter),Number(capacity),Number(leadTime),Number(horizon)];const startSeconds=seconds(start);const endSeconds=seconds(end);if(!providerTimezone||!recurrence||!effectiveFrom||numbers.some(value=>!Number.isInteger(value))||!Number.isInteger(startSeconds)||!Number.isInteger(endSeconds)){setMessage("Complete all availability fields with valid values.");return;}setBusy(true);setMessage("");try{await api(`/v1/service-offering-versions/${selected.versionId}/availability`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({providerTimezone,slotDurationSeconds:numbers[0],bufferBeforeSeconds:numbers[1],bufferAfterSeconds:numbers[2],capacity:numbers[3],bookingLeadTimeSeconds:numbers[4],bookingHorizonSeconds:numbers[5],rules:[{recurrence,effectiveFrom:new Date(effectiveFrom).toISOString(),windows:[{kind:"WORKING",weekday:Number(weekday),startSeconds,endSeconds}]}],exceptions:[]})});setSelected(undefined);await load(clinic);setMessage("Availability saved.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to save availability.");}finally{setBusy(false);}}return <main className="main"><h1>Clinic Availability</h1><section className="panel"><h2>Service availability</h2>{items.map(item=>{const detail=item.versionId?details[item.versionId]:undefined;const windows=detail?.rules.flatMap(rule=>rule.windows.filter(window=>window.kind==="WORKING").map(window=>`${weekdays[window.weekday]??`Day ${window.weekday}`} ${time(window.startSeconds)}–${time(window.endSeconds)}`))??[];return <article className="card" key={item.id}><strong>{item.name}</strong><p className="muted">Service: {item.status} · Version: {item.versionStatus??"Not configured"} · Availability: {item.availabilityStatus??"Not configured"} · Public Discovery: {item.publicDiscoveryStatus??"Not published"}</p>{detail?<><p className="muted">{detail.status} · {detail.providerTimezone} · {detail.slotDurationSeconds}s slots · Capacity {detail.capacity} · Lead {detail.bookingLeadTimeSeconds}s · Horizon {detail.bookingHorizonSeconds}s</p><p className="muted">Working windows: {windows.length?windows.join("; "):"None configured"}</p></>:null}{canManage&&item.status==="ACTIVE"&&item.versionId&&item.versionStatus==="ACTIVE"&&!item.availabilityStatus?<button disabled={busy} onClick={()=>openCreate(item)}>Add availability</button>:null}{!item.versionId?<p className="muted">This service has no version available for availability configuration.</p>:null}{item.versionId&&item.versionStatus!=="ACTIVE"?<p className="muted">Availability can be configured after this service has an active version.</p>:null}</article>;})}{items.length===0?<p className="muted">No clinic services are available for configuration.</p>:null}</section>{canManage&&selected?<section className="panel"><h2>Add availability for {selected.name}</h2><label>Provider timezone<input disabled={busy} placeholder="Asia/Kolkata" value={providerTimezone} onChange={e=>setProviderTimezone(e.target.value)}/></label><label>Slot duration (seconds)<input disabled={busy} inputMode="numeric" value={slotDuration} onChange={e=>setSlotDuration(e.target.value)}/></label><label>Buffer before (seconds)<input disabled={busy} inputMode="numeric" value={bufferBefore} onChange={e=>setBufferBefore(e.target.value)}/></label><label>Buffer after (seconds)<input disabled={busy} inputMode="numeric" value={bufferAfter} onChange={e=>setBufferAfter(e.target.value)}/></label><label>Capacity<input disabled={busy} inputMode="numeric" value={capacity} onChange={e=>setCapacity(e.target.value)}/></label><label>Booking lead time (seconds)<input disabled={busy} inputMode="numeric" value={leadTime} onChange={e=>setLeadTime(e.target.value)}/></label><label>Booking horizon (seconds)<input disabled={busy} inputMode="numeric" value={horizon} onChange={e=>setHorizon(e.target.value)}/></label><label>Weekly recurrence<input disabled={busy} placeholder="FREQ=WEEKLY;BYDAY=MO,WE" value={recurrence} onChange={e=>setRecurrence(e.target.value)}/></label><label>Effective from<input disabled={busy} type="datetime-local" value={effectiveFrom} onChange={e=>setEffectiveFrom(e.target.value)}/></label><label>Weekday (1 Monday through 7 Sunday)<input disabled={busy} inputMode="numeric" value={weekday} onChange={e=>setWeekday(e.target.value)}/></label><label>Working start<input disabled={busy} type="time" value={start} onChange={e=>setStart(e.target.value)}/></label><label>Working end<input disabled={busy} type="time" value={end} onChange={e=>setEnd(e.target.value)}/></label><button disabled={busy} onClick={()=>void create()}>{busy?"Saving…":"Save availability"}</button><button disabled={busy} onClick={()=>setSelected(undefined)}>Cancel</button></section>:null}{!canManage?<p className="muted">Your current clinic role is read-only.</p>:null}{message?<p className="muted">{message}</p>:null}<p className="muted">Editing, deactivation, and removal are not shown because the existing API exposes only availability creation and read.</p></main>}
export function ClinicDoctors(){const[c,setC]=useState<Context>();const[items,setItems]=useState<Doctor[]>([]);const[doctorProfileId,setDoctorProfileId]=useState("");const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);async function load(value:Context){const clinic=value.clinics[0];setC(value);if(clinic)setItems((await api<{items:Doctor[]}>(`/v1/provider/clinics/${clinic.id}/doctors`)).items);}useEffect(()=>{void context().then(load).catch(x=>setMessage(x instanceof Error?x.message:"Unable to load clinic doctors."));},[]);if(!c&&!message)return <section className="page-loading">Loading clinic doctors…</section>;const clinic=c?.clinics[0];const canManage=clinic!==undefined&&clinic.role!=="CLINIC_STAFF";const active=items.filter(item=>item.connectionStatus==="ACCEPTED");const pending=items.filter(item=>item.connectionStatus==="REQUESTED");async function refresh(){const current=await context();await load(current);}async function request(){if(!clinic||!doctorProfileId.trim())return;setBusy(true);setMessage("");try{await api("/v1/network-connections",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({source:{kind:"CLINIC",clinicId:clinic.id},target:{kind:"DOCTOR",doctorProfileId:doctorProfileId.trim()}})});setDoctorProfileId("");await refresh();setMessage("Doctor connection requested.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to request doctor connection.");}finally{setBusy(false);}}async function transition(item:Doctor,operation:"accept"|"reject"|"revoke"){if(!item.connectionId)return;if((operation==="reject"||operation==="revoke")&&!confirm(`${operation==="revoke"?"Remove":"Reject"} this doctor relationship?`))return;setBusy(true);setMessage("");try{await api(`/v1/network-connections/${item.connectionId}/${operation}`,{method:"POST"});await refresh();setMessage(operation==="accept"?"Doctor connection accepted.":operation==="reject"?"Doctor connection rejected.":"Doctor relationship removed.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to update doctor relationship.");}finally{setBusy(false);}}function row(item:Doctor){const inbound=item.connectionStatus==="REQUESTED"&&item.connectionInitiatorKind==="DOCTOR";return <li key={item.connectionId??item.id}><strong>{item.displayName??"Unnamed doctor"}</strong><br/><span className="muted">Profile: {item.status} · Professional verification: {item.professionalVerificationStatus}</span><br/><span className="status-badge">{item.connectionStatus}</span>{canManage&&item.connectionStatus==="ACCEPTED"?<button disabled={busy} onClick={()=>void transition(item,"revoke")}>Remove doctor</button>:null}{canManage&&inbound?<><button disabled={busy} onClick={()=>void transition(item,"accept")}>Accept</button><button className="secondary-button" disabled={busy} onClick={()=>void transition(item,"reject")}>Reject</button></>:null}</li>;}return <section className="page"><p className="eyebrow">Clinic operations</p><h1>Clinic Doctors</h1>{canManage?<section className="panel"><h2>Connect a doctor</h2><p className="muted">Enter the existing doctor profile ID. The backend verifies the doctor and your clinic authorization.</p><label>Doctor profile ID<input disabled={busy} value={doctorProfileId} onChange={event=>setDoctorProfileId(event.target.value)}/></label><button disabled={busy||!doctorProfileId.trim()} onClick={()=>void request()}>{busy?"Requesting…":"Request connection"}</button></section>:<p className="muted">Your current clinic role is read-only.</p>}<section className="panel"><h2>Active doctors</h2>{active.length?<ul>{active.map(row)}</ul>:<div className="empty-state">No active doctor relationships.</div>}</section><section className="panel"><h2>Pending connections</h2>{pending.length?<ul>{pending.map(row)}</ul>:<div className="empty-state">No pending doctor connections or invitations.</div>}</section>{message?<p className={message.includes("Unable")?"error":"feedback"}>{message}</p>:null}</section>}
export function ClinicAppointments(){const[c,setC]=useState<Context>();const[items,setItems]=useState<Appointment[]>([]);const[message,setMessage]=useState("");useEffect(()=>{void context().then(async value=>{setC(value);const clinic=value.clinics[0];if(clinic)setItems((await api<{items:Appointment[]}>(`/v1/provider/clinics/${clinic.id}/appointments`)).items);}).catch(x=>setMessage(x instanceof Error?x.message:"Unable to load clinic appointments."));},[]);if(!c&&!message)return <main className="login panel">Loading clinic appointments…</main>;return <main className="main"><h1>Clinic Appointments</h1><section className="panel"><h2>Appointments</h2><p className="muted">Appointments are read-only in this Provider Web phase.</p><ul>{items.map(item=><li key={item.id}><strong>{item.serviceName}</strong> · {item.status}<br/><span className="muted">{new Date(item.startsAt).toLocaleString()} – {new Date(item.endsAt).toLocaleString()} · Reference: {item.id}</span></li>)}</ul>{items.length===0&&!message?<p className="muted">No clinic appointments are available.</p>:null}{message?<p className="error">{message}</p>:null}</section></main>}

type ServiceVersion={id:string;status:string;effectiveFrom:string;effectiveTo:string|null;price:{currency:string;amountMinor:string}};
type EffectiveVersions=Record<string,ServiceVersion|null>;

export function DoctorServices(){
  const[c,setC]=useState<Context>();const[items,setItems]=useState<Service[]>([]);const[effective,setEffective]=useState<EffectiveVersions>({});const[name,setName]=useState("");const[description,setDescription]=useState("");const[versioning,setVersioning]=useState<Service>();const[versionNumber,setVersionNumber]=useState("1");const[effectiveFrom,setEffectiveFrom]=useState("");const[currency,setCurrency]=useState("INR");const[amountMinor,setAmountMinor]=useState("");const[message,setMessage]=useState("");const[busy,setBusy]=useState(false);
  async function load(value:Context){setC(value);if(!value.doctor){setItems([]);setEffective({});return;}const services=(await api<{items:Service[]}>("/v1/provider/doctor/services")).items;setItems(services);const values=await Promise.all(services.map(async service=>{if(!service.versionId)return [service.id,null] as const;try{return [service.id,await api<ServiceVersion>(`/v1/service-offerings/${service.id}/versions/applicable?at=${encodeURIComponent(new Date().toISOString())}`)] as const;}catch{return [service.id,null] as const;}}));setEffective(Object.fromEntries(values));}
  useEffect(()=>{void context().then(load).catch(x=>setMessage(x instanceof Error?x.message:"Unable to load doctor services."));},[]);
  const doctor=c?.doctor;
  async function refresh(){await load(await context());}
  async function create(){if(!doctor||!name.trim())return;setBusy(true);setMessage("");try{await api("/v1/service-offerings",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({owner:{kind:"DOCTOR",doctorProfileId:doctor.id},name:name.trim(),description:description.trim()||null,status:"DRAFT"})});setName("");setDescription("");await refresh();setMessage("Service created as Draft.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to create the service.");}finally{setBusy(false);}}
  async function activate(service:Service){setBusy(true);setMessage("");try{await api(`/v1/service-offerings/${service.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({name:service.name,description:service.description??null,status:"ACTIVE"})});await refresh();setMessage("Service activated.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to activate the service.");}finally{setBusy(false);}}
  function openVersion(service:Service){setVersioning(service);setVersionNumber("1");setEffectiveFrom("");setCurrency("INR");setAmountMinor("");setMessage("");}
  async function createVersion(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!versioning)return;const number=Number(versionNumber);const at=new Date(effectiveFrom);if(!Number.isInteger(number)||number<=0||Number.isNaN(at.getTime())||!/^[A-Z]{3}$/.test(currency.trim().toUpperCase())||!/^(0|[1-9]\d*)$/.test(amountMinor)){setMessage("Enter a valid version number, effective date, ISO currency, and non-negative price in minor units.");return;}setBusy(true);setMessage("");try{await api(`/v1/service-offerings/${versioning.id}/versions`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({versionNumber:number,status:"ACTIVE",effectiveFrom:at.toISOString(),currency:currency.trim().toUpperCase(),amountMinor})});setVersioning(undefined);await refresh();setMessage("Active service version created.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to create the service version.");}finally{setBusy(false);}}
  async function createExposure(service:Service){setBusy(true);setMessage("");try{await api("/v1/service-exposures",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({serviceOfferingId:service.id})});await refresh();setMessage("Service exposure created as Draft.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to create the service exposure.");}finally{setBusy(false);}}
  async function changeExposure(service:Service,operation:"publish"|"unpublish"){if(!service.exposureId)return;setBusy(true);setMessage("");try{await api(`/v1/service-exposures/${service.exposureId}/${operation}`,{method:"POST"});await refresh();setMessage(operation==="publish"?"Service exposure published. Platform Discovery approval remains separate.":"Service exposure unpublished.");}catch(x){setMessage(x instanceof Error?x.message:"Unable to update the service exposure.");}finally{setBusy(false);}}
  if(!c&&!message)return <main className="login panel">Loading doctor services…</main>;
  if(!doctor)return <ProviderShell><section className="panel"><h1>My Services</h1><p className="muted">A doctor profile is required to manage doctor-owned services.</p></section></ProviderShell>;
  return <ProviderShell><section className="page"><p className="eyebrow">Doctor operations</p><h1>My Services</h1><section className="panel"><h2>Public Discovery prerequisites</h2><p>Professional verification: <span className="status-badge">{doctor.professionalVerificationStatus}</span></p><p className="muted">A service must be active, have an effective active version, active availability, and a published exposure. Platform Discovery approval remains a separate Platform Admin action.</p></section><section className="panel"><h2>Add service</h2><label>Name<input disabled={busy} value={name} onChange={event=>setName(event.target.value)}/></label><label>Description<textarea disabled={busy} value={description} onChange={event=>setDescription(event.target.value)}/></label><button disabled={busy||!name.trim()} onClick={()=>void create()}>{busy?"Creating…":"Add service"}</button></section><section className="panel"><h2>Doctor-owned services</h2>{items.length?<ul>{items.map(service=>{const current=effective[service.id];return <li key={service.id}><strong>{service.name}</strong>{service.description?` — ${service.description}`:""}<p className="muted">Service: {service.status} · Latest version: {service.versionStatus??"Not configured"} · Effective version: {current?`${current.status} (${current.price.currency} ${current.price.amountMinor} minor units)`:"None currently effective"} · Availability: {service.availabilityStatus??"Not configured"} · Exposure: {service.exposureStatus??"Not created"} · Platform Discovery: {service.publicDiscoveryStatus??"Not published"}</p>{service.status!=="ACTIVE"?<button disabled={busy} onClick={()=>void activate(service)}>Activate service</button>:null}{service.status==="ACTIVE"?<button disabled={busy} onClick={()=>openVersion(service)}>Create active version</button>:null}{!service.exposureId?<button disabled={busy} onClick={()=>void createExposure(service)}>Create exposure</button>:null}{service.exposureStatus==="DRAFT"||service.exposureStatus==="UNPUBLISHED"?<button disabled={busy} onClick={()=>void changeExposure(service,"publish")}>Publish exposure</button>:null}{service.exposureStatus==="PUBLISHED"?<button className="secondary-button" disabled={busy} onClick={()=>void changeExposure(service,"unpublish")}>Unpublish exposure</button>:null}</li>;})}</ul>:<div className="empty-state">No doctor-owned services yet. Create your first service to begin configuration.</div>}</section>{versioning?<section className="panel"><h2>Create active version for {versioning.name}</h2><p className="muted">Availability is configured separately after version creation.</p><form onSubmit={event=>void createVersion(event)}><label>Version number<input disabled={busy} inputMode="numeric" value={versionNumber} onChange={event=>setVersionNumber(event.target.value)}/></label><label>Effective from<input disabled={busy} required type="datetime-local" value={effectiveFrom} onChange={event=>setEffectiveFrom(event.target.value)}/></label><label>Currency<input disabled={busy} maxLength={3} value={currency} onChange={event=>setCurrency(event.target.value)}/></label><label>Price amount (minor units)<input disabled={busy} inputMode="numeric" value={amountMinor} onChange={event=>setAmountMinor(event.target.value)}/></label><div className="actions"><button disabled={busy} type="submit">{busy?"Creating…":"Create active version"}</button><button className="secondary-button" disabled={busy} onClick={()=>setVersioning(undefined)} type="button">Cancel</button></div></form></section>:null}{message?<p className={message.includes("Unable")||message.includes("valid")?"error":"feedback"}>{message}</p>:null}</section></ProviderShell>;
}

